from typing import List


class Solution:
    def judgePoint24(self, nums: List[int]) -> bool:
        EPS = 1e-6

        def dfs(arr: List[float]) -> bool:
            # If only one number remains, check whether it is 24
            if len(arr) == 1:
                return abs(arr[0] - 24) < EPS

            n = len(arr)
            for i in range(n):
                for j in range(i + 1, n):
                    a, b = arr[i], arr[j]
                    rest = [arr[k] for k in range(n) if k != i and k != j]

                    # All possible results from combining a and b
                    candidates = [a + b, a - b, b - a, a * b]
                    if abs(b) > EPS:
                        candidates.append(a / b)
                    if abs(a) > EPS:
                        candidates.append(b / a)

                    for value in candidates:
                        if dfs(rest + [value]):
                            return True

            return False

        return dfs([float(x) for x in nums])

from typing import List


class Solution:
    def makesquare(self, nums: List[int]) -> bool:
        if not nums or len(nums) < 4:
            return False

        total = sum(nums)
        if total % 4 != 0:
            return False

        target = total // 4
        nums.sort(reverse=True)

        # If the largest stick is longer than one side, impossible
        if nums[0] > target:
            return False

        sides = [0, 0, 0, 0]

        def dfs(index: int) -> bool:
            if index == len(nums):
                return sides[0] == sides[1] == sides[2] == sides[3] == target

            used_lengths = set()
            for i in range(4):
                # Symmetry pruning: same current side length => same state
                if sides[i] in used_lengths:
                    continue
                if sides[i] + nums[index] > target:
                    continue

                used_lengths.add(sides[i])
                sides[i] += nums[index]
                if dfs(index + 1):
                    return True
                sides[i] -= nums[index]

                # If we tried putting it on an empty side and failed,
                # there is no need to try other empty sides.
                if sides[i] == 0:
                    break

            return False

        return dfs(0)
